                    while(u!=s){
                        int i=pre[u];
                        edges[i].w-=delta;
                        edges[i^1].w+=delta;
                        u=pre[u];
                    }
                    total_flow+=delta;
                    low=INF;
                }
                break;
            }
        }
        if(pushed) continue;
        int minDist=t+1;
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(edges[i].w && dist[v]<minDist){
                minDist=dist[v];
                arc[u]=i;
            }
        }
        gap[dist[u]]--;
        if(gap[dist[u]]==0) break;
        dist[u]=minDist+1;
        gap[dist[u]]++;
        u=pre[u];
    }
    return total_flow;
