        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid2[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] == 'Z') {
                    stone[0][i][j] = 2;
                } else if (grid1[i][j] == 'Y') {
                    stone[0][i][j] = 1;
                } else if (Character.isDigit(grid1[i][j])) {
                    sci[i][j] = grid1[i][j] - '0';
